<?php

namespace Tests\Support;

// Small generated fixtures; no GD requirement, real media or personal data.
trait IdentityPhotoFixtures
{
    protected function identityPhotoBytes(string $extension = 'png'): string
    {
        $samples = [
            'png' => '',
            'jpg' => '',
            'webp' => '',
        ];

        return base64_decode($samples[$extension === 'jpeg' ? 'jpg' : $extension], true);
    }
}
